def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    lowest_amount = min(values)
    return {
        "value": lowest_amount,
        "trace": {
            "values": values,
            "lowest_amount": lowest_amount,
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
